/**
 * 隨機分配人格給玩家
 */
export function assignPersonalities(playerCount) {
    const shuffled = [...personalities].sort(() => Math.random() - 0.5);
    return shuffled.slice(0, playerCount);
}
/**
 * 根據人格生成壓力台詞
 */
export function getPressureLine(personality, situation) {
    const lines = personality.pressureLines[situation === 'accused' ? 'whenAccused' :
        situation === 'defending' ? 'whenDefending' :
            situation === 'attacking' ? 'whenAttacking' :
                'whenUncertain'];
    return lines[Math.floor(Math.random() * lines.length)];
}
